=== FILE: sync_fifo.v ===
// sync_fifo: parameterizable synchronous FIFO, first-word fall-through.
// Implements interface_spec.md per microarchitecture.md.
`default_nettype none

module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer PW = $clog2(DEPTH);      // pointer width
    localparam integer CW = $clog2(DEPTH + 1);  // count width

    // Sized constants, sliced from 32-bit values so every operand matches.
    localparam [31:0]   LAST_32  = DEPTH - 1;
    localparam [31:0]   DEPTH_32 = DEPTH;
    localparam [31:0]   ONE_32   = 1;
    localparam [PW-1:0] LAST     = LAST_32[PW-1:0];
    localparam [PW-1:0] PONE     = ONE_32[PW-1:0];
    localparam [CW-1:0] DEPTH_C  = DEPTH_32[CW-1:0];
    localparam [CW-1:0] CONE     = ONE_32[CW-1:0];

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [PW-1:0]    wr_ptr;
    reg [PW-1:0]    rd_ptr;
    reg [CW-1:0]    count_q;

    assign full    = (count_q == DEPTH_C);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;
    assign rd_data = mem[rd_ptr];

    wire wr_acc = wr_en && !full;
    wire rd_acc = rd_en && !empty;

    // Control: pointers and occupancy, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {PW{1'b0}};
            rd_ptr  <= {PW{1'b0}};
            count_q <= {CW{1'b0}};
        end else begin
            if (wr_acc)
                wr_ptr <= (wr_ptr == LAST) ? {PW{1'b0}} : (wr_ptr + PONE);
            if (rd_acc)
                rd_ptr <= (rd_ptr == LAST) ? {PW{1'b0}} : (rd_ptr + PONE);
            if (wr_acc && !rd_acc)
                count_q <= count_q + CONE;
            else if (rd_acc && !wr_acc)
                count_q <= count_q - CONE;
        end
    end

    // Datapath storage: not reset, written only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc)
            mem[wr_ptr] <= wr_data;
    end

`ifdef FORMAL
    // Design-intent assertions (not part of simulation or synthesis).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid)
            assume (!rst_n);
    end

    always @(*) begin
        if (f_past_valid) begin
            assert (full  == (count_q == DEPTH_C));
            assert (empty == (count_q == {CW{1'b0}}));
            assert (!(full && empty));
            assert (count_q <= DEPTH_C);
            assert (wr_ptr <= LAST);
            assert (rd_ptr <= LAST);
            assert (((rd_ptr + count_q) % DEPTH) == wr_ptr);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n)) begin
            assert (count_q == {CW{1'b0}});
            assert (wr_ptr == {PW{1'b0}});
            assert (rd_ptr == {PW{1'b0}});
        end
        if (f_past_valid && $past(rst_n)) begin
            if ($past(wr_acc) && !$past(rd_acc))
                assert (count_q == $past(count_q) + CONE);
            if ($past(rd_acc) && !$past(wr_acc))
                assert (count_q == $past(count_q) - CONE);
            if ($past(wr_acc) == $past(rd_acc))
                assert (count_q == $past(count_q));
            if ($past(wr_en) && $past(full))
                assert (wr_ptr == $past(wr_ptr));
            if ($past(rd_en) && $past(empty))
                assert (rd_ptr == $past(rd_ptr));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: sync_fifo_tb.v ===
// Self-checking testbench for sync_fifo.
// Two lanes (DEPTH 8 x WIDTH 8, DEPTH 5 x WIDTH 12) on shared stimulus, each
// checked every cycle against a reference queue, with coverage points.
`default_nettype none
`timescale 1ns/1ps

module sync_fifo_tb_lane #(
    parameter integer LANE  = 0,
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8,
    parameter integer MAXW  = 12
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            wr_en,
    input  wire            rd_en,
    input  wire [MAXW-1:0] stim_data,
    input  wire            done,
    output wire [31:0]     passed,
    output wire [31:0]     failed
);

    localparam integer PW = $clog2(DEPTH);
    localparam integer CW = $clog2(DEPTH + 1);

    localparam [31:0]   LAST_32  = DEPTH - 1;
    localparam [31:0]   DEPTH_32 = DEPTH;
    localparam [31:0]   ONE_32   = 1;
    localparam [PW-1:0] LAST_P   = LAST_32[PW-1:0];
    localparam [PW-1:0] ONE_P    = ONE_32[PW-1:0];
    localparam [CW-1:0] DEPTH_C  = DEPTH_32[CW-1:0];
    localparam [CW-1:0] LAST_C   = LAST_32[CW-1:0];
    localparam [CW-1:0] ONE_C    = ONE_32[CW-1:0];

    wire [WIDTH-1:0] wdata = stim_data[WIDTH-1:0];
    wire             full;
    wire             empty;
    wire [WIDTH-1:0] rd_data;
    wire [CW-1:0]    count;

    sync_fifo #(.DEPTH(DEPTH), .WIDTH(WIDTH)) dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wdata),
        .full    (full),
        .rd_en   (rd_en),
        .rd_data (rd_data),
        .empty   (empty),
        .count   (count)
    );

    // Reference queue.
    reg [WIDTH-1:0] q [0:DEPTH-1];
    reg [PW-1:0]    head    = {PW{1'b0}};
    reg [PW-1:0]    tail    = {PW{1'b0}};
    reg [CW-1:0]    cnt     = {CW{1'b0}};
    reg             started = 1'b0;

    wire m_wr = wr_en && (cnt != DEPTH_C);
    wire m_rd = rd_en && (cnt != {CW{1'b0}});

    // Coverage counters.
    integer cov_fill      = 0;  // 100: filled to full
    integer cov_wr_full   = 0;  // 101: write while full
    integer cov_drain     = 0;  // 102: drained to empty
    integer cov_rd_empty  = 0;  // 103: read while empty
    integer cov_both_emp  = 0;  // 104: write+read when empty
    integer cov_both_full = 0;  // 105: write+read when full
    integer cov_both_mid  = 0;  // 106: write+read in between
    integer cov_wrap_wr   = 0;  // 107: write pointer wrap
    integer cov_wrap_rd   = 0;  // 108: read pointer wrap
    integer cov_rst_busy  = 0;  // 109: reset while holding entries

    always @(posedge clk) begin
        if (!rst_n) begin
            if (started && (cnt != {CW{1'b0}}))
                cov_rst_busy <= cov_rst_busy + 1;
            head    <= {PW{1'b0}};
            tail    <= {PW{1'b0}};
            cnt     <= {CW{1'b0}};
            started <= 1'b1;
        end else if (started) begin
            if (wr_en && (cnt == DEPTH_C))
                cov_wr_full <= cov_wr_full + 1;
            if (rd_en && (cnt == {CW{1'b0}}))
                cov_rd_empty <= cov_rd_empty + 1;
            if (wr_en && rd_en) begin
                if (cnt == {CW{1'b0}})
                    cov_both_emp <= cov_both_emp + 1;
                else if (cnt == DEPTH_C)
                    cov_both_full <= cov_both_full + 1;
                else
                    cov_both_mid <= cov_both_mid + 1;
            end
            if (m_wr && !m_rd && (cnt == LAST_C))
                cov_fill <= cov_fill + 1;
            if (m_rd && !m_wr && (cnt == ONE_C))
                cov_drain <= cov_drain + 1;

            if (m_wr) begin
                q[tail] <= wdata;
                if (tail == LAST_P) begin
                    tail        <= {PW{1'b0}};
                    cov_wrap_wr <= cov_wrap_wr + 1;
                end else begin
                    tail <= tail + ONE_P;
                end
            end
            if (m_rd) begin
                if (head == LAST_P) begin
                    head        <= {PW{1'b0}};
                    cov_wrap_rd <= cov_wrap_rd + 1;
                end else begin
                    head <= head + ONE_P;
                end
            end
            if (m_wr && !m_rd)
                cnt <= cnt + ONE_C;
            else if (m_rd && !m_wr)
                cnt <= cnt - ONE_C;
        end
    end

    // Checking.
    reg [31:0] n_pass   = 32'd0;
    reg [31:0] n_fail   = 32'd0;
    reg        cov_done = 1'b0;

    assign passed = n_pass;
    assign failed = n_fail;

    task check;
        input         ok;
        input integer id;
        begin
            if (ok) begin
                n_pass = n_pass + 32'd1;
            end else begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo_tb lane %0d (DEPTH %0d WIDTH %0d): check %0d failed at %0t: full=%b empty=%b count=%0d rd_data=%h | ref count=%0d ref data=%h",
                       LANE, DEPTH, WIDTH, id, $time, full, empty, count, rd_data, cnt, q[head]);
            end
        end
    endtask

    always @(negedge clk) begin
        if (started) begin
            check(full === (cnt == DEPTH_C), 1);
            check(empty === (cnt == {CW{1'b0}}), 2);
            check(count === cnt, 3);
            check(!(full && empty), 4);
            if (cnt != {CW{1'b0}})
                check(rd_data === q[head], 5);
        end
        if (done && !cov_done) begin
            cov_done = 1'b1;
            check(cov_fill      > 0, 100);
            check(cov_wr_full   > 0, 101);
            check(cov_drain     > 0, 102);
            check(cov_rd_empty  > 0, 103);
            check(cov_both_emp  > 0, 104);
            check(cov_both_full > 0, 105);
            check(cov_both_mid  > 0, 106);
            check(cov_wrap_wr   > 0, 107);
            check(cov_wrap_rd   > 0, 108);
            check(cov_rst_busy  > 0, 109);
        end
    end

endmodule

module sync_fifo_tb;

    reg         clk     = 1'b0;
    reg         rst_n   = 1'b0;
    reg         wr_en   = 1'b0;
    reg         rd_en   = 1'b0;
    reg  [11:0] wr_data = 12'h000;
    reg         done    = 1'b0;
    reg  [31:0] rng     = 32'h1234_5678;
    reg  [8*64-1:0] nonce;
    integer     got;
    integer     passed;
    integer     failed;

    wire [31:0] pass_a;
    wire [31:0] fail_a;
    wire [31:0] pass_b;
    wire [31:0] fail_b;

    always #5 clk = ~clk;

    sync_fifo_tb_lane #(.LANE(0), .DEPTH(8), .WIDTH(8), .MAXW(12)) u_a (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
        .stim_data(wr_data), .done(done), .passed(pass_a), .failed(fail_a)
    );

    sync_fifo_tb_lane #(.LANE(1), .DEPTH(5), .WIDTH(12), .MAXW(12)) u_b (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
        .stim_data(wr_data), .done(done), .passed(pass_b), .failed(fail_b)
    );

    task step_rng;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    // One cycle of directed stimulus, applied at the falling edge.
    task drive;
        input rs;
        input w;
        input r;
        begin
            @(negedge clk);
            step_rng;
            rst_n   = rs;
            wr_en   = w;
            rd_en   = r;
            wr_data = rng[11:0];
        end
    endtask

    // One cycle of random stimulus with request probabilities wp/256, rp/256.
    task drive_rand;
        input       rs;
        input [7:0] wp;
        input [7:0] rp;
        begin
            @(negedge clk);
            step_rng;
            rst_n = rs;
            wr_en = (rng[7:0] < wp);
            rd_en = (rng[15:8] < rp);
            step_rng;
            wr_data = rng[11:0];
        end
    endtask

    initial begin
        nonce = {(8*64){1'b0}};
        got = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (got == 0)
            nonce = {(8*64){1'b0}};

        // Reset.
        repeat (3) drive(1'b0, 1'b0, 1'b0);

        // Read while empty, write+read when empty, then drain the single entry.
        drive(1'b1, 1'b0, 1'b1);
        drive(1'b1, 1'b0, 1'b1);
        drive(1'b1, 1'b1, 1'b1);
        drive(1'b1, 1'b0, 1'b1);

        // Fill to full (both lanes) and keep writing while full.
        repeat (10) drive(1'b1, 1'b1, 1'b0);

        // Write+read when full, then in between.
        repeat (3) drive(1'b1, 1'b1, 1'b1);

        // Drain to empty and keep reading while empty.
        repeat (10) drive(1'b1, 1'b0, 1'b1);

        // Partially fill, then reset during traffic.
        repeat (3) drive(1'b1, 1'b1, 1'b0);
        drive(1'b0, 1'b1, 1'b1);
        drive(1'b0, 1'b1, 1'b0);

        // Steady streaming with pointer wrap-around.
        repeat (3)  drive(1'b1, 1'b1, 1'b0);
        repeat (20) drive(1'b1, 1'b1, 1'b1);

        // Random phases.
        repeat (400) drive_rand(1'b1, 8'd200, 8'd60);
        repeat (2)   drive_rand(1'b0, 8'd200, 8'd200);
        repeat (400) drive_rand(1'b1, 8'd60,  8'd200);
        repeat (400) drive_rand(1'b1, 8'd128, 8'd128);
        repeat (400) drive_rand(1'b1, 8'd240, 8'd240);
        repeat (400) drive_rand(1'b1, 8'd30,  8'd30);
        repeat (400) drive_rand(1'b1, 8'd220, 8'd100);
        repeat (3)   drive_rand(1'b0, 8'd128, 8'd128);
        repeat (400) drive_rand(1'b1, 8'd100, 8'd220);

        // Idle, then evaluate coverage and report.
        repeat (5) drive(1'b1, 1'b0, 1'b0);
        @(negedge clk);
        done = 1'b1;
        repeat (2) @(negedge clk);
        #1;
        passed = pass_a + pass_b;
        failed = fail_a + fail_b;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
